import{_ as o,o as r,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）","description":"好，我们继续进入： 🧭 ✅ 本章目标： 追踪模块之间的依赖关系 输出可视化的依赖图（.dot for Graphviz，或 HTML 可视化） 用图形一眼看清模块结构、主干路径、孤立模块等 🧱 示例结构 graphvizbundler/├── src/│ ├── main.mjs。","frontmatter":{"title":"第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"好，我们继续进入： 🧭 ✅ 本章目标： 追踪模块之间的依赖关系 输出可视化的依赖图（.dot for Graphviz，或 HTML 可视化） 用图形一眼看清模块结构、主干路径、孤立模块等 🧱 示例结构 graphvizbundler/├── src/│ ├── main.mjs。","sidebarWeight":49,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）.md"}'),a={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）.md"};function e(g,t,p,i,d,l){return r(),s("div",null,[...t[0]||(t[0]=[n('<div><h1 id="第十二章-生成模块依赖图可视化-支持-graphviz-和-html" tabindex="-1">第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML） <a class="header-anchor" href="#第十二章-生成模块依赖图可视化-支持-graphviz-和-html" aria-label="Permalink to &quot;第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）&quot;">​</a></h1><blockquote><p>本节目标：理解“第十二章：生成模块依赖图可视化（支持 Graphviz 和 HTML）”的核心思路，并能把它用于实际开发或面试表达。 好，我们继续进入：</p></blockquote><p><strong>🧭</strong> ✅ 本章目标：</p><ul><li>追踪模块之间的依赖关系</li><li>输出可视化的依赖图（.dot for Graphviz，或 HTML 可视化）</li><li>用图形一眼看清模块结构、主干路径、孤立模块等</li></ul><p><strong>🧱</strong> <strong>示例结构</strong> graphvizbundler/├── src/│ ├── main.mjs│ ├── a.mjs│ ├── b.mjs│ └── config.json├── bundler.js└── graph.dot # ✅ 输出的 Graphviz 源码</p><p><strong>📄</strong> <strong>示例代码</strong><strong>src/a.mjs</strong> import config from &#39;./config.json&#39;;export const msg = &#39;A + &#39; + config.appName; <strong>src/b.mjs</strong> export const b = &#39;module B&#39;; <strong>src/main.mjs</strong> import { msg } from &#39;./a.mjs&#39;;import { b } from &#39;./b.mjs&#39;; console.log(msg, b);</p><p><strong>✍️</strong> <strong>bundler.js 添加可视化输出</strong> 我们在打包完成后，<strong>生成 .dot 文件</strong>，可用 Graphviz 生成图： <strong>✅</strong> <strong>步骤一：修改 parseModule() 添加模块名字段</strong> return { id: id++, name: path.relative(__dirname, absPath), absPath, rawCode, deps, isESM, isJSON: ext === &#39;.json&#39;};</p><p><strong>✅</strong> <strong>步骤二：添加 generateGraphDot(modules) 函数</strong> function generateGraphDot(modules) { const lines = [&#39;digraph G {&#39;, &#39; node [shape=box, style=filled, color=lightblue];&#39;]; for (const mod of modules) { for (const dep of mod.deps) { const targetAbs = path.resolve(path.dirname(mod.absPath), dep.endsWith(&#39;.json&#39;) || dep.endsWith(&#39;.mjs&#39;) ? dep : dep + &#39;.js&#39;); const target = modules.find(m =&gt; m.absPath === targetAbs); if (target) { lines.push(<code> &quot;${mod.name}&quot; -\\&gt; &quot;${target.name}&quot;;</code>); } } } lines.push(&#39;}&#39;); return lines.join(&#39;\\n&#39;);}</p><p><strong>✅</strong> <strong>步骤三：打包完成后输出 .dot 文件</strong> const graphDot = generateGraphDot(modules);fs.writeFileSync(&#39;graph.dot&#39;, graphDot);console.log(&#39;✅ 依赖图导出完成：graph.dot&#39;);</p><p><strong>🖼️</strong> <strong>使用 Graphviz 生成图</strong><strong>安装 Graphviz（如未安装）：</strong></p><ul><li>macOS: brew install graphviz</li><li>Ubuntu: sudo apt install graphviz</li></ul><p><strong>生成 PNG 图：</strong> dot -Tpng graph.dot -o graph.png 也可以生成 SVG： dot -Tsvg graph.dot -o graph.svg</p><p><strong>✅</strong> <strong>示例输出（graph.dot）</strong> digraph G { node [shape=box, style=filled, color=lightblue]; &quot;src/main.mjs&quot; -&gt; &quot;src/a.mjs&quot;; &quot;src/main.mjs&quot; -&gt; &quot;src/b.mjs&quot;; &quot;src/a.mjs&quot; -&gt; &quot;src/config.json&quot;;}</p><p><strong>✅</strong> <strong>效果图示（Graphviz 渲染后）</strong> +------------------+| src/main.mjs |+------------------+ | \\ | \\ v v+------------+ +------------+| src/a.mjs | | src/b.mjs |+------------+ +------------+ | v+-------------------+| src/config.json |+-------------------+</p><p><strong>✅</strong> <strong>本章成果</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>功能</strong></td><td><strong>实现</strong></td></tr><tr><td>构建模块依赖图</td><td>✔</td></tr><tr><td>输出 Graphviz .dot 文件</td><td>✔</td></tr><tr><td>支持 JSON/JS/ESM 模块</td><td>✔</td></tr><tr><td>可视化调用结构</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>第十三章预告（可选方向）</strong></p><p>下一步我们可以探索：</p><ol start="2"><li><strong>输出 HTML 图形界面（支持点击查看模块内容）</strong></li><li><strong>打包多个入口文件，生成多个 bundle 文件（多页面应用场景）</strong></li><li><strong>生成每个模块的体积统计（可视化优化空间）</strong></li></ol><p>你想继续哪个方向？我可以继续带你写下一章 ✅ &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const c=o(a,[["render",e]]);export{m as __pageData,c as default};
